app<-source('app.R')$value
checks<-0L
check<-function(ok,label) {if(!isTRUE(ok)) stop('FAIL: ',label,call.=FALSE);checks<<-checks+1L;cat('PASS:',label,'\n')}
errors<-function(expr) inherits(tryCatch(force(expr),error=identity),'error')
r<-pc_power();check(r$n==64 && r$power>=0.8 && r$power<0.81,'two independent means d=0.5 needs 64 per group for 80 percent power')
check(pc_power(design='paired')$n==34,'paired dz=0.5 needs 34 complete pairs')
check(pc_power(design='one.sample')$n==34,'one-sample planning uses observations rather than two groups')
r<-pc_power(dropout=0.2);check(r$n==64 && r$recruit==80,'dropout changes recruitment but not analyzable N')
r<-pc_power(solve='power',n=64);check(abs(r$power-stats::power.t.test(n=64,delta=0.5,sd=1,type='two.sample',strict=TRUE)$power)<1e-10,'power at fixed N agrees with the noncentral t calculation')
r<-pc_power(design='anova',effect=0.25,groups=3);check(r$power>=0.8 && stats::power.anova.test(groups=3,n=r$n-1,between.var=0.25^2*3/2,within.var=1)$power<0.8,'ANOVA f conversion and integer N reach target power with minimal N')
r<-pc_power(design='proportions');check(r$power>=0.8 && r$n>50,'two-proportion planning reaches target after rounding')
check(all(diff(pc_power()$curve$Power)>0),'power sensitivity rises with sample size')
for(args in list(list(effect=0),list(alpha=1),list(target=0.01),list(dropout=1),list(design='paired',solve='power',n=2.5),list(design='anova',groups=2.5),list(design='proportions',p1=0.5,p2=0.5))) check(errors(do.call(pc_power,args)),'invalid planning assumptions are rejected')
xy<-pc_check_table(data.frame(X=c(1,10,100),A=c(10,100,1000),B=c(100,1000,10000)))
r<-pc_transform(xy,'xy','log10');check(identical(r$X,xy$X) && identical(as.numeric(r$A),c(1,2,3)),'default XY transform preserves X and transforms all Y columns')
r<-pc_transform(xy,'xy','log10',target='x');check(identical(r$A,xy$A) && identical(as.numeric(r$X),c(0,1,2)),'X-only transform preserves all Y observations')
r<-pc_transform(xy,'xy','log10',target='both');check(r$X[2]=='1' && r$A[2]=='2','explicit XY transform can include X and Y')
r<-pc_transform(xy,'xy','log10',target='selected',columns='A');check(identical(r$X,xy$X)&&identical(r$B,xy$B)&&r$A[1]=='1','selected-series transform preserves unselected Y and X')
g<-pc_check_table(pc_example('grouped')$table);r<-pc_transform(g,'grouped','ln');check(identical(g[1:2],r[1:2]),'grouped transform preserves factor labels')
m<-pc_check_table(data.frame(ID=101:103,Group=c('a','b','c'),Y=c(10,100,1000)))
r<-pc_transform(m,'multiple','log10',target='selected',columns='Y');check(identical(r[1:2],m[1:2])&&r$Y[1]=='1','multiple-variable transform preserves numeric IDs and metadata')
check(errors(pc_transform(m,'multiple','ln')),'multiple-variable transform requires explicit measurement selection')
check(errors(pc_transform(g,'grouped','ln',target='selected',columns=names(g)[1])),'factor columns cannot be selected as measurements')
check(errors(pc_transform(data.frame(A=c(0,1)),'column','ln')),'log transform rejects nonpositive selected observations')
check(errors(pc_transform(pc_example('survival')$table,'survival','ln')),'survival structural columns are protected')
r<-pc_read_text('A\tB\r\n1\t2\r\n3\t\r\n\r\n');check(nrow(r)==2&&is.na(r[2,2]),'whole-table parsing accepts CRLF terminators and preserves missing values')
r<-pc_read_text('A;B\n1;2\n', ';');check(ncol(r)==2&&r[1,2]=='2','whole-table parser supports an explicit semicolon delimiter')
check(errors(pc_read_text('A,B\n1,2,3')),'whole-table parser rejects ragged rows')
shiny::testServer(app,{
 do.call(session$setInputs,pc_defaults());session$flushReact();before<-raw()
 session$setInputs(paste_data='NewA\tNewB\n10\t20\n30\t40\n',paste_delimiter='auto',apply_paste=1);session$flushReact()
 check(identical(names(raw()),c('NewA','NewB'))&&raw()[2,2]=='40','whole-table replacement reaches active worksheet')
 session$setInputs(undo_data=1);session$flushReact();check(identical(raw(),before),'one undo restores the entire prior table')
 session$setInputs(paste_data='A,B\nwrong,2',apply_paste=2);session$flushReact();check(identical(raw(),before)&&grepl('Table unchanged',replacement_message()),'invalid replacement is atomic and shows an inline error')
 session$setInputs(power_open=1,power_design='two.sample',power_solve='n',power_effect=0.5,power_alpha=0.05,power_target=0.8,power_n=20,power_groups=3,power_p1=0.3,power_p2=0.5,power_dropout=0,power_calculate=1);session$flushReact()
 check(grepl('64',output$power_metrics,fixed=TRUE),'power calculator exposes computed sample size in the app')
 check(identical(raw(),before),'power planning does not change source observations')
 session$setInputs(power_help_open=1);session$flushReact()
 check(grepl('Enter assumptions',output$power_status$html,fixed=TRUE),'Help opens a fresh power-planning dialog without duplicate input IDs')
 session$setInputs(paste_data='Control,Treated\n10,100\n100,1000',paste_delimiter=',',apply_paste=3);session$flushReact()
 original<-raw();original_id<-active_sheet()
 session$setInputs(y_min='1',y_max='10000',transform_kind='log10',transform_target='measurements',apply_transform=1);session$flushReact()
 check(raw()[1,1]=='1' && raw()[2,2]=='3' && active_sheet()!=original_id,'transform action creates a separate derived worksheet')
 check(identical(settings()$y_min,'') && identical(settings()$y_max,''),'derived measurements reset axis limits to valid automatic scaling')
 check(identical(pc_read_text(workbook()[[original_id]]$data_tsv),original),'derived worksheet preserves source observations')
})
cat(checks,'power, transform and whole-table replacement checks passed.\n')
